(function(){
function decode(value){if(!value)return null;try{var text=decodeURIComponent(Array.prototype.map.call(atob(value.replace(/-/g,"+").replace(/_/g,"/")),function(c){return "%"+("00"+c.charCodeAt(0).toString(16)).slice(-2);}).join(""));return JSON.parse(text);}catch(e){return null;}}
function encode(value){var bytes=unescape(encodeURIComponent(JSON.stringify(value)));return btoa(bytes).replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/,"");}
function el(tag,className,text){var node=document.createElement(tag);if(className)node.className=className;if(text!==undefined)node.textContent=text;return node;}
function money(value,currency){var number=Number(value)||0;try{return new Intl.NumberFormat("sr-RS",{style:"currency",currency:currency&&currency.length===3?currency:"RSD",maximumFractionDigits:2}).format(number);}catch(e){return number.toFixed(2)+" "+(currency||"RSD");}}
function clip(value,max){value=String(value||"").trim();return value.length>max?value.slice(0,max):value;}
document.querySelectorAll(".wf-instance[data-wf-component=\"product-detail\"]").forEach(function(host){
if(host.dataset.wfDetailReady==="true")return;
host.dataset.wfDetailReady="true";
var root=host.querySelector(".wf-detail");
if(!root)return;
var status=root.querySelector("[data-wf-status]"),panel=root.querySelector("[data-wf-product]"),gallery=root.querySelector("[data-wf-gallery]"),meta=root.querySelector("[data-wf-meta]"),name=root.querySelector("[data-wf-name]"),price=root.querySelector("[data-wf-price]"),stock=root.querySelector("[data-wf-stock]"),description=root.querySelector("[data-wf-description]"),specs=root.querySelector("[data-wf-specs]"),specBody=root.querySelector("[data-wf-spec-body]"),related=root.querySelector("[data-wf-related]"),relatedGrid=root.querySelector("[data-wf-related-grid]");
if(window.parent!==window&&(host.dataset.wfCatalogBridge==="true"||host.hasAttribute("data-wf-provider-preview")||host.hasAttribute("data-wf-provider-preview-error")))host.dataset.wfCatalogBridge="true";

function cancelOffers(){if(window.ElastycCatalogOffers)window.ElastycCatalogOffers.cancel(host);window.ElastycCatalogOffersQueue=(window.ElastycCatalogOffersQueue||[]).filter(function(entry){return entry.host!==host;});}
function scheduleOffers(items){if(window.ElastycCatalogOffers){window.ElastycCatalogOffers.load(host,root,items);return;}window.ElastycCatalogOffersQueue=(window.ElastycCatalogOffersQueue||[]).filter(function(entry){return entry.host!==host;});window.ElastycCatalogOffersQueue.push({host:host,root:root,items:items});}
function detailUrl(id){var path=root.dataset.detailUrl||"/proizvod";return path+(path.indexOf("?")<0?"?":"&")+"id="+encodeURIComponent(id||"");}

var pendingId="",serial=0;
function requestId(){serial+=1;var suffix=Math.random().toString(36).replace(/[^a-z0-9]/g,"").slice(0,8);var prefix=("00000000"+serial.toString(36)).slice(-8);return (prefix+suffix).slice(0,40);}
function productId(){var params=new URLSearchParams(window.location.search);var id=clip(params.get("id"),80);if(!id||id.indexOf("/")>=0||id.indexOf("\\")>=0)return"";return id;}
function showStatus(text,error){if(panel)panel.hidden=true;status.textContent=text;if(error)status.dataset.error="true";else status.removeAttribute("data-error");}
function render(data){if(!data||data.found!==true){showStatus("Proizvod nije pronađen.",true);return;}status.textContent="";status.removeAttribute("data-error");panel.hidden=false;panel.setAttribute("data-wf-item-id",String(data.id||""));while(meta.firstChild)meta.removeChild(meta.firstChild);var links=[];function catalogLink(href,label){var anchor=el("a","wf-detail__link",label);anchor.href=href;return anchor;}if(data.brand)links.push(catalogLink((root.dataset.catalogUrl||"/proizvodi")+"?df="+encodeURIComponent("field11:"+data.brand),data.brand));if(data.category)links.push(catalogLink((root.dataset.catalogUrl||"/proizvodi")+"?category="+encodeURIComponent(data.category),data.category));links.forEach(function(link,index){if(index)meta.appendChild(document.createTextNode(" · "));meta.appendChild(link);});meta.hidden=!links.length;name.textContent=data.name||data.id||"";price.textContent=money(data.price,data.currency);price.hidden=root.dataset.showPrice==="false";var known=data["stock-known"]!==false;stock.textContent=known?(Number(data.stock)>0?"Na stanju: "+data.stock:"Nema na stanju"):"Stanje na upit";stock.dataset.empty=known&&Number(data.stock)<=0?"true":"false";stock.hidden=root.dataset.showStock==="false";var text=String(data.description||"").trim();description.textContent=text;description.hidden=!text;gallery.innerHTML="";var images=Array.isArray(data.gallery)&&data.gallery.length?data.gallery:[{url:"/commonAssets/Images/coming_soon_transparent.png"}];var main=el("img","wf-detail__image");main.fetchPriority="high";main.decoding="async";function show(url,alt){main.src=url||"";main.alt=alt||"";}show(images[0].url,data.name||"");gallery.appendChild(main);if(images.length>1){var thumbs=el("div","wf-detail__thumbs");images.forEach(function(image,index){var button=el("button","wf-detail__thumb"),thumb=el("img");button.type="button";if(index===0)button.setAttribute("aria-current","true");thumb.src=image.url||"";thumb.alt="";button.appendChild(thumb);button.addEventListener("click",function(){show(image.url,data.name||"");thumbs.querySelectorAll("button").forEach(function(other){other.removeAttribute("aria-current");});button.setAttribute("aria-current","true");});thumbs.appendChild(button);});gallery.appendChild(thumbs);}specBody.innerHTML="";var rows=Array.isArray(data.characteristics)?data.characteristics:[];rows.forEach(function(row){var tr=el("tr");tr.appendChild(el("th","",row.name||""));tr.appendChild(el("td","",row.value||""));specBody.appendChild(tr);});specs.hidden=!rows.length;while(relatedGrid.firstChild)relatedGrid.removeChild(relatedGrid.firstChild);var others=Array.isArray(data.related)?data.related:[];others.forEach(function(item){if(!item||!item.id)return;var card=el("a","wf-detail__card");card.setAttribute("data-wf-item-id",String(item.id));card.href=detailUrl(item.id);var image=el("img");image.src=item["image-url"]||"/commonAssets/Images/coming_soon_transparent.png";image.alt=item.name||"";image.loading="lazy";card.appendChild(image);var body=el("span","wf-detail__card-body");if(item.brand)body.appendChild(el("span","wf-detail__card-brand",item.brand));body.appendChild(el("strong","",item.name||item.id));var regular=el("del"),actual=el("span","",money(item.price,item.currency)),discount=el("small");regular.setAttribute("data-wf-regular-price","");regular.hidden=true;actual.setAttribute("data-wf-price","");actual.hidden=root.dataset.showPrice==="false";discount.setAttribute("data-wf-discount","");discount.hidden=true;body.appendChild(regular);body.appendChild(actual);body.appendChild(discount);card.appendChild(body);relatedGrid.appendChild(card);});related.hidden=!relatedGrid.children.length;scheduleOffers([data].concat(others));}
function load(){cancelOffers();var id=productId();if(!id){showStatus("Proizvod nije izabran.",true);return;}var request=requestId();pendingId=request;status.textContent="Učitavanje…";status.removeAttribute("data-error");if(panel)panel.hidden=true;var input={id:id};if(host.dataset.wfCatalogBridge==="true"){window.parent.postMessage({type:"elastyc-webfront-catalog-provider-v1",pageKey:host.dataset.wfPage||"",instanceKey:host.dataset.wfInstance||"",input:input,requestId:request},"*");return;}var url=new URL(host.dataset.wfProviderUrl,window.location.href);url.searchParams.set("wf_input",encode(input));fetch(url.toString(),{credentials:"same-origin",headers:{Accept:"application/json"}}).then(function(response){if(!response.ok)throw new Error("HTTP "+response.status);return response.json();}).then(function(payload){if(pendingId!==request)return;render(payload.data!==undefined?payload.data:payload);}).catch(function(error){if(pendingId!==request)return;showStatus(error&&error.message?error.message:"Proizvod trenutno nije dostupan.",true);});}
window.addEventListener("message",function(event){if(event.source!==window.parent)return;var data=event.data;if(!data||data.type!=="elastyc-webfront-catalog-provider-result-v1")return;if(data.binding)return;if(data.requestId!==pendingId||data.instanceKey!==host.dataset.wfInstance)return;if(!data.ok){showStatus(data.error||"Proizvod trenutno nije dostupan.",true);return;}render(data.data);});
var initial=decode(host.dataset.wfInitialData);if(initial&&typeof initial==="object"){render(initial);return;}
if(!productId()){showStatus("Proizvod nije izabran.",true);return;}
var previewError=host.dataset.wfProviderPreviewError||"";
if(previewError){showStatus(previewError,true);return;}
load();
});
})();

(function(global){
"use strict";
if(global.ElastycCatalogOffers)return;
var states=new WeakMap(),pending={};
function money(value,currency){return new Intl.NumberFormat("sr-RS",{style:"currency",currency:/^[A-Z]{3}$/.test(currency||"")?currency:"RSD",maximumFractionDigits:2}).format(value);}
function flag(root,key,fallback){return root.dataset[key]===undefined?fallback:root.dataset[key]==="true";}
function status(root,message){var node=root.querySelector("[data-wf-offers-status]");if(node){node.textContent=message;node.hidden=!message;}}
function requestId(){return Date.now().toString(36)+Math.random().toString(36).slice(2,14);}
function cancel(host){
  var previous=states.get(host);
  if(previous)previous.cancelled=true;
  Object.keys(pending).forEach(function(key){if(pending[key].host===host){var entry=pending[key];delete pending[key];global.clearTimeout(entry.timer);entry.reject(new Error("superseded"));}});
}
function request(host,ids,state){
  if(host.dataset.wfCatalogBridge==="true"){
    return new Promise(function(resolve,reject){
      var id=requestId();
      var timer=global.setTimeout(function(){delete pending[id];reject(new Error("unavailable"));},15000);
      pending[id]={host:host,state:state,resolve:resolve,reject:reject,timer:timer};
      global.parent.postMessage({type:"elastyc-webfront-catalog-provider-v1",pageKey:host.dataset.wfPage||"",instanceKey:host.dataset.wfInstance||"",binding:"offers",input:{ids:ids},requestId:id},"*");
    });
  }
  var url=new URL(host.dataset.wfQueryOffersUrl,global.location.href);
  var input=JSON.stringify({ids:ids});
  var bytes=unescape(encodeURIComponent(input));
  url.searchParams.set("wf_input",btoa(bytes).replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/,""));
  return global.fetch(url.toString(),{credentials:"same-origin",cache:"no-store",headers:{Accept:"application/json"}})
    .then(function(response){if(!response.ok)throw new Error("unavailable");return response.json();})
    .then(function(payload){if(payload.ok!==true||!payload.data||!Array.isArray(payload.data.items))throw new Error("unavailable");return payload.data;});
}
function apply(root,item,state){
  var showPrice=flag(root,"showPrice",true),showStock=flag(root,"showStock",true);
  var showRegular=flag(root,"showRegularPrice",true),showDiscount=flag(root,"showDiscountBadge",true);
  var priceKnown=item["price-known"]===true&&typeof item.price==="number"&&isFinite(item.price)&&item.price>=0;
  var stockKnown=item["stock-known"]===true&&typeof item.stock==="number"&&isFinite(item.stock);
  if((showPrice&&!priceKnown)||(showStock&&!stockKnown))state.unknown=true;
  root.querySelectorAll("[data-wf-item-id]").forEach(function(node){
    if(node.getAttribute("data-wf-item-id")!==item.id)return;
    var price=node.querySelector("[data-wf-price]"),regular=node.querySelector("[data-wf-regular-price]"),discount=node.querySelector("[data-wf-discount]"),stock=node.querySelector("[data-wf-stock]");
    if(price){price.hidden=!showPrice;if(showPrice&&priceKnown){price.textContent=money(item.price,item.currency);price.setAttribute("data-wf-price-state","current");}}
    var active=priceKnown&&item["discount-active"]===true&&typeof item["regular-price"]==="number"&&item["regular-price"]>item.price;
    if(regular){regular.hidden=!(showPrice&&showRegular&&active);if(!regular.hidden)regular.textContent=money(item["regular-price"],item.currency);}
    if(discount){discount.hidden=!(showDiscount&&active&&typeof item["discount-percent"]==="number"&&item["discount-percent"]>0);if(!discount.hidden)discount.textContent="−"+new Intl.NumberFormat("sr-RS",{maximumFractionDigits:2}).format(item["discount-percent"])+"%";}
    if(stock){stock.hidden=!showStock;if(showStock){stock.textContent=stockKnown?(item.stock>0?"Na stanju: "+new Intl.NumberFormat("sr-RS",{maximumFractionDigits:4}).format(item.stock):"Nema na stanju"):"Stanje na upit";stock.dataset.known=stockKnown?"true":"false";stock.dataset.empty=stockKnown&&item.stock<=0?"true":"false";}}
  });
}
function load(host,root,items){
  cancel(host);
  if(!host.dataset.wfQueryOffersUrl)return;
  if(!flag(root,"showPrice",true)&&!flag(root,"showStock",true)&&!flag(root,"showDiscountBadge",true))return;
  var ids=[];
  items.forEach(function(item){var id=String(item.id||"");if(id&&ids.indexOf(id)<0)ids.push(id);});
  if(!ids.length){status(root,"");return;}
  var state={cancelled:false,unknown:false};states.set(host,state);
  status(root,"Provera cene i stanja…");
  var batches=[];for(var i=0;i<ids.length;i+=50)batches.push(ids.slice(i,i+50));
  var chain=Promise.resolve();
  batches.forEach(function(batch){
    chain=chain.then(function(){
      if(state.cancelled)return;
      return request(host,batch,state).then(function(data){
        if(state.cancelled)return;
        var received=[];
        data.items.forEach(function(item){if(batch.indexOf(item.id)<0)return;received.push(item.id);apply(root,item,state);});
        if(received.length!==batch.length)state.unknown=true;
      });
    });
  });
  chain.then(function(){if(!state.cancelled)status(root,state.unknown?"Za deo proizvoda cena ili stanje su na upit.":"");})
    .catch(function(){if(!state.cancelled)status(root,"Provera aktuelne cene i stanja trenutno nije dostupna.");});
}
global.addEventListener("message",function(event){
  if(event.source!==global.parent)return;
  var data=event.data;
  if(!data||data.type!=="elastyc-webfront-catalog-provider-result-v1"||data.binding!=="offers")return;
  var entry=pending[data.requestId];
  if(!entry||entry.host.dataset.wfInstance!==data.instanceKey)return;
  delete pending[data.requestId];global.clearTimeout(entry.timer);
  if(entry.state.cancelled)return;
  if(!data.ok||!data.data||!Array.isArray(data.data.items)){entry.reject(new Error("unavailable"));return;}
  entry.resolve(data.data);
});
global.ElastycCatalogOffers={load:load,cancel:cancel};
var queue=global.ElastycCatalogOffersQueue||[];
global.ElastycCatalogOffersQueue=[];
queue.forEach(function(entry){load(entry.host,entry.root,entry.items);});
})(window);
